import {
  CONVERSATION_STATUSES,
  ConversationStatus,
  IConversationEntity,
} from './conversation.entity';
import { ConversationClosedError } from './exceptions/conversation-closed.error';
import { InvalidConversationError } from './exceptions/invalid-conversation.error';

/** Values needed to create a new conversation. */
export interface CreateConversationProps {
  /** Identifier for the new conversation, generated by the caller. */
  id: string;
  /** Workspace of the authenticated caller, never taken from the request body. */
  workspaceId: string;
  subject: string;
  /** Defaults to `open`. */
  status?: ConversationStatus;
  /** Current time (UTC), supplied by the caller so tests control the clock. */
  now: Date;
}

/**
 * A customer conversation. Created only through {@link Conversation.create},
 * which enforces the creation rules.
 */
export class Conversation implements IConversationEntity {
  private constructor(
    readonly id: string,
    readonly subject: string,
    readonly status: ConversationStatus,
    readonly workspaceId: string,
    readonly createdAt: Date,
    readonly updatedAt: Date,
    readonly assignedAgentId?: string,
    readonly assignedAt?: Date,
    readonly assignedBy?: string,
    /** Changes made so far; storage writes a change only if this is still current. */
    readonly version = 0,
  ) {}

  /**
   * Creates a new, unassigned conversation.
   *
   * - The subject is trimmed and must not be blank.
   * - The status defaults to `open` and must be `open` or `closed`.
   * - `createdAt` and `updatedAt` both start at `now`.
   *
   * @throws {InvalidConversationError} when the subject or status breaks a rule.
   */
  static create(props: CreateConversationProps): Conversation {
    const subject = props.subject.trim();
    if (subject === '') {
      throw new InvalidConversationError('subject', 'Conversation subject must not be blank');
    }

    const status = props.status ?? 'open';
    if (!CONVERSATION_STATUSES.includes(status)) {
      throw new InvalidConversationError(
        'status',
        `Conversation status must be one of: ${CONVERSATION_STATUSES.join(', ')}`,
      );
    }

    return new Conversation(
      props.id,
      subject,
      status,
      props.workspaceId,
      new Date(props.now),
      new Date(props.now),
    );
  }

  /**
   * Rebuilds a conversation from its stored form, so storage can hand back a
   * plain entity and the domain can still apply its behaviour (`assign`) to it.
   * The stored data was validated when it was created, so nothing is re-checked.
   */
  static restore(entity: IConversationEntity): Conversation {
    return new Conversation(
      entity.id,
      entity.subject,
      entity.status,
      entity.workspaceId,
      new Date(entity.createdAt),
      new Date(entity.updatedAt),
      entity.assignedAgentId,
      entity.assignedAt && new Date(entity.assignedAt),
      entity.assignedBy,
      entity.version,
    );
  }

  /**
   * Removes the current assignment. Conversations are immutable, so this
   * returns the unassigned conversation rather than changing this one.
   *
   * - The three assignment fields are cleared together (absent, not `null`) and
   *   `updatedAt` becomes `now`.
   * - The version goes up by one.
   * - A conversation nobody is assigned to comes back as the same instance,
   *   untouched, so callers can skip the write.
   * - Unlike assigning, this is allowed on a closed conversation: the rule that
   *   closed conversations are frozen covers assigning and reassigning only.
   */
  unassign(now: Date): Conversation {
    if (this.assignedAgentId === undefined) {
      return this;
    }
    return new Conversation(
      this.id,
      this.subject,
      this.status,
      this.workspaceId,
      this.createdAt,
      new Date(now),
      undefined,
      undefined,
      undefined,
      this.version + 1,
    );
  }

  /**
   * Assigns the conversation to an agent. Conversations are immutable, so this
   * returns the assigned conversation rather than changing this one.
   *
   * - A closed conversation cannot be assigned, even to its current agent.
   * - Assigning the current agent again changes nothing: the same instance
   *   comes back, with `assignedAt`, `assignedBy` and `updatedAt` untouched.
   * - Any other agent replaces the current one (the three assignment fields
   *   are set together, `updatedAt` becomes `now`, the version goes up by one).
   *
   * The caller checks that `agentId` is a real agent of this workspace and
   * that `assignedBy` may assign; the conversation does not know agents.
   *
   * @throws {ConversationClosedError} when the conversation is closed.
   */
  assign(agentId: string, assignedBy: string, now: Date): Conversation {
    if (this.status === 'closed') {
      throw new ConversationClosedError(this.id);
    }
    if (this.assignedAgentId === agentId) {
      return this;
    }
    return new Conversation(
      this.id,
      this.subject,
      this.status,
      this.workspaceId,
      this.createdAt,
      new Date(now),
      agentId,
      new Date(now),
      assignedBy,
      this.version + 1,
    );
  }
}
